function monthlySavings(currentVcpu, currentMonthlyCostUsd, recommendedVcpu) {
  if (currentVcpu <= 0) {
    throw new Error('currentVcpu must be greater than 0');
  }
  const costPerVcpu = currentMonthlyCostUsd / currentVcpu;
  return Math.round((currentVcpu - recommendedVcpu) * costPerVcpu * 100) / 100;
}

